BEGIN;
CREATE TABLE IF NOT EXISTS audit_engagements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),period_id uuid NOT NULL REFERENCES fiscal_periods(id),name text NOT NULL,stage text NOT NULL DEFAULT 'acceptance' CHECK(stage IN ('acceptance','data_validation','planning_risk','pbc_evidence','fieldwork','findings_conclusions','adjustments_review','completion_reporting')),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','completed','archived')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_blockers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),engagement_id uuid NOT NULL REFERENCES audit_engagements(id),code text NOT NULL,description text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved','waived')),resolved_by uuid REFERENCES users(id),resolved_at timestamptz);
CREATE TABLE IF NOT EXISTS audit_gates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),engagement_id uuid NOT NULL REFERENCES audit_engagements(id),stage text NOT NULL,code text NOT NULL,required boolean NOT NULL DEFAULT true,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','passed','failed','waived')),UNIQUE(engagement_id,stage,code));
CREATE TABLE IF NOT EXISTS human_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),engagement_id uuid REFERENCES audit_engagements(id),actor_id uuid NOT NULL REFERENCES users(id),decision_type text NOT NULL,decision text NOT NULL CHECK(decision IN ('approve','reject','waive','transition')),rationale text NOT NULL,digest text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_stage_history (id bigserial PRIMARY KEY,engagement_id uuid NOT NULL REFERENCES audit_engagements(id),from_stage text NOT NULL,to_stage text NOT NULL,decision_id uuid NOT NULL REFERENCES human_decisions(id),actor_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
COMMIT;
